from pathlib import Path
import importlib.util, json, hashlib, re
import numpy as np
base=Path('research_cognition_physics/archive_1161_')
p=base/'1165'
core=[base/'research_note_1165.md']+[p/n for n in ('admission.md','proof.md','check.py','results.json','NEXT.md')]
before={str(x.relative_to(base)):hashlib.sha256(x.read_bytes()).hexdigest() for x in core}
s=importlib.util.spec_from_file_location('review1165_author_replay',p/'check.py')
m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
fresh=m.calculate();saved=json.loads((p/'results.json').read_text(encoding='utf-8-sig'))
counts={'leaves':0,'floats':0,'max_float_absolute_difference':0.}
def cmp(a,b,key=''):
 if isinstance(b,dict):
  assert a.keys()==b.keys(),key
  for k in b:cmp(a[k],b[k],key+'/'+k)
 elif isinstance(b,list):
  assert len(a)==len(b),key
  for i,(x,y) in enumerate(zip(a,b)):cmp(x,y,key+'/'+str(i))
 else:
  counts['leaves']+=1
  if isinstance(b,float):
   counts['floats']+=1
   d=abs(a-b);counts['max_float_absolute_difference']=max(counts['max_float_absolute_difference'],d)
   assert d<=3e-10+1e-9*abs(b),(key,a,b)
  else:assert a==b,(key,a,b)
cmp(fresh,saved)
links=0
for f in core:
 assert hashlib.sha256(f.read_bytes()).hexdigest()==before[str(f.relative_to(base))]
 if f.suffix=='.md':
  text=f.read_bytes().decode('utf-8')
  assert '\r' not in text,f
  assert all(ord(x)>=32 or x in '\n\t' for x in text),f
  assert text.count('$$')%2==0,f
  for ref in re.findall(r'\]\(([^)]+)\)',text):
   if '://' not in ref and not ref.startswith('#'):
    target=f.parent/ref.split('#')[0]
    assert target.exists() or target.resolve()==(p/'review.md').resolve(),(f,ref)
    links+=1
sourcehashes={str((p/k).resolve()):hashlib.sha256((p/k).read_bytes()).hexdigest() for k in m.SOURCES}
for f in (base.parent/'archive_1159_1160/1160/check.py',base.parent/'archive_1106_1119/1111/check.py'):
 sourcehashes[str(f.resolve())]=hashlib.sha256(f.read_bytes()).hexdigest()
print(json.dumps({'status':'PASS','core_sha256':before,'source_sha256':sourcehashes,'replay_comparison':counts,
 'static_check':{'local_link_count':links,'formula_blocks_balanced':True,'control_characters_absent':True},
 'fresh_summary':{'orbit_error':fresh['unitary_orbit']['maximum_identity_error'],
 'affine_error':fresh['common_scale_and_tangent']['affine_error'],
 'original_D_spectrum_norm_residual':fresh['full_material']['D_spectrum_error']}},ensure_ascii=False,indent=2))
